#include <stdio.h>
#include <stdlib.h>
int main(void) {
    int n = 5;
    int *a = malloc((size_t)n * sizeof *a);
    if (!a) return 1;
    for (int i = 0; i < n; i++) a[i] = i * i;
    for (int i = 0; i < n; i++) printf("%d ", a[i]);
    printf("\n");
    free(a);
    a = NULL;
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
int main(void) {
    int cap = 2, len = 0;
    int *a = malloc((size_t)cap * sizeof *a);
    if (!a) return 1;
    for (int v = 1; v <= 6; v++) {
        if (len == cap) {
            int *tmp = realloc(a, (size_t)(cap * 2) * sizeof *a);
            if (!tmp) { free(a); return 1; }
            a = tmp; cap *= 2;
        }
        a[len++] = v;
    }
    for (int i = 0; i < len; i++) printf("%d ", a[i]);
    printf("cap=%d\n", cap);
    free(a);
    return 0;
}
